 true, '2026-03-09 08:54:22.415286+00', null, true, null, false, 'Punakha Dzong', null), ('febcedbc-5c4a-4e8e-9bc9-9a030d3959c5', 'Memorial Chorten', 'Thimphu', 'stupa', null, '1.0', null, null, '6.00', '500.00', true, null, 5, 80, null, null, null, null, ARRAY['https://res.cloudinary.com/dvivq8oji/image/upload/v1774163537/activities/thimphu/memorial-chorten-1.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163542/activities/thimphu/memorial-chorten-2.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163548/activities/thimphu/memorial-chorten-3.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163553/activities/thimphu/memorial-chorten-4.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163559/activities/thimphu/memorial-chorten-5.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163564/activities/thimphu/memorial-chorten-6.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163568/activities/thimphu/memorial-chorten-7.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163573/activities/thimphu/memorial-chorten-8.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163578/activities/thimphu/memorial-chorten-9.jpg','https://res.cloudinary.com/dvivq8oji/image/upload/v1774163583/activities/thimphu/memorial-chorten-10.jpg'], null, null, null, null, null, null, false, null, false, '2026-03-09 08:37:34.211017+00', null, true, null, false, 'Memorial Chorten', null);
